			{Time: 50, Observations: []Observation{{ID: "L", X: 1e308}}},
			{Time: 100},
			{Time: 200, Observations: []Observation{{ID: "L", X: 1e308}}},
		}}); err != nil {
			t.Fatal(err)
		}
		before, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
