// 帧序号，而不是在保存时返回普通编码错误。
func TestImportComputedNonFinitePose(t *testing.T) {
	huge := func() Config {
		return Config{
			InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
			InitialVariance: 0, MaxInterval: 100, MergeDistance: 10,
		}
	}
	type tc struct {
		name   string
		cfg    Config
		frames []Frame
		frame  int
